 public static final class Renderer {final Session session;final Map<String,Processor> processors=new HashMap<>();final Map<String,Pro.Chain> chains=new HashMap<>();final Map<String,float[]> busBuffers=new HashMap<>(),keys=new HashMap<>();final Map<String,Fx> scratch=new HashMap<>();final ArrayList<String> keyed=new ArrayList<>();final Pro.Chain masterChain=new Pro.Chain();public final Pro.Loudness loudness=new Pro.Loudness();float[] temp=new float[0],post=new float[0];double limiterGain=1;Pro.TempoMap map;int mapBpm=-1,mapSig=-1,mapHash=0;public volatile float peak,peakLeft,peakRight,limiterDb,masterReduction;public volatile float clickLevel=.12f;public volatile boolean overloaded,meterLoudness=true;/** Last 8192 mono output samples (for the spectrum view) and smoothed stereo correlation (−1…+1). *//** Plugin delay compensation: per-path delay lines so channels with look-ahead inserts stay in time. */final Map<String,Pro.DelayLine> pdcLines=new HashMap<>();final Map<String,Integer> pdcLat=new HashMap<>(),pdcBusIn=new HashMap<>();boolean pdcOn;int pdcM;public final float[] scope=new float[8192];public volatile int scopePos;public volatile float correlation=1;double corrLR,corrLL=1e-9,corrRR=1e-9;public Renderer(Session s){session=s;}public int masterLatency(){computePdc();return masterChain.latency(session.masterInserts)+(pdcOn?pdcM:0);}Pro.Chain chain(Track t){Pro.Chain c=chains.get(t.id);if(c==null){c=new Pro.Chain();chains.put(t.id,c);}return c;}static boolean hasLatency(Track t){if(t.bypassFx)return false;for(Pro.Insert i:t.inserts)if(i.enabled&&Pro.LIMITER.equals(i.kind))return true;return false;}/** Works out each channel's insert latency and the delays that line every path up at bus inputs and at the master. */void computePdc(){boolean any=false;for(Track t:session.tracks)if(hasLatency(t)){any=true;break;}if(!any)for(Track b:session.buses)if(hasLatency(b)){any=true;break;}if(!any){if(pdcOn){pdcLines.clear();pdcOn=false;}pdcM=0;return;}pdcOn=true;pdcLat.clear();pdcBusIn.clear();boolean solo=false;for(Track t:session.tracks)if(t.solo)solo=true;int m=0;for(Track t:session.tracks){if(t.mute||(solo&&!t.solo))continue;int l=hasLatency(t)?chain(t).latency(t.inserts):0;pdcLat.put(t.id,l);Track out=t.output==null?null:session.bus(t.output);if(out==null)m=Math.max(m,l);else pdcBusIn.merge(out.id,l,Math::max);for(Pro.Send x:t.sends)if(session.bus(x.bus)!=null)pdcBusIn.merge(x.bus,l,Math::max);}for(Track b:session.buses){if(b.mute)continue;int l=hasLatency(b)?chain(b).latency(b.inserts):0;pdcLat.put(b.id,l);m=Math.max(m,pdcBusIn.getOrDefault(b.id,0)+l);}pdcM=m;}void pdcAdd(String key,float[] src,float[] dst,int n,int delay){if(delay<=0&&!pdcLines.containsKey(key)){for(int i=0;i<n*2;i++)dst[i]+=src[i];return;}Pro.DelayLine d=pdcLines.get(key);if(d==null){d=new Pro.DelayLine();pdcLines.put(key,d);}d.process(src,dst,n,Math.max(0,delay));}static float[] buffer(Map<String,float[]> m,String id,int n){float[] b=m.get(id);if(b==null||b.length<n*2){b=new float[Math.max(n*2,1024)];m.put(id,b);}return b;}public Pro.TempoMap tempoMap(){int h=session.tempoChanges.hashCode();if(map==null||mapBpm!=session.bpm||mapSig!=session.timeSignature||mapHash!=h){map=new Pro.TempoMap(session);mapBpm=session.bpm;mapSig=session.timeSignature;mapHash=h;}return map;}void sum(Track t,long pos,int n,float[] into){sumTimeline(t,pos,n,into);Clip l=t.launched;if(l!=null)launcher(t,l,pos,n,into);}void launcher(Track t,Clip l,long pos,int n,float[] into){long from=Math.max(pos,t.launchAt),to=Math.min(pos+n,t.launchStop);if(t.launchStop<=pos){if(t.launched==l)t.launched=null;return;}if(from>=to)return;int len=Math.max(1,l.length);for(long at=from;at<to;at++){int local=(int)((at-t.launchAt)%len),dst=(int)(at-pos)*2,src=l.offset+local;if(src>=l.source.frames()){into[dst]=into[dst+1]=0;continue;}double e=clipEnvelope(l,local);into[dst]=(float)(l.source.sample(src,0)*e);into[dst+1]=(float)(l.source.sample(src,1)*e);}}void sumTimeline(Track t,long pos,int n,float[] into){Arrays.fill(into,0,n*2,0);boolean xf=t.autoCrossfade&&t.clips.size()>1;int xlen=session.crossfadeFrames;int index=-1;for(Clip c:t.clips){index++;long from=Math.max(pos,c.start),to=Math.min(pos+n,c.start+c.length);if(from>=to)continue;boolean overlapped=false;if(xf)for(Clip o:t.clips)if(o!=c&&o.start<to&&o.start+o.length>from){overlapped=true;break;}for(long at=from;at<to;at++){int dst=(int)(at-pos)*2,src=(int)(at-c.start)+c.offset;if(src>=0&&src<c.source.frames()){double envelope=clipEnvelope(c,(int)(at-c.start));if(overlapped)envelope*=Pro.overlapGain(t,c,index,at,xlen);into[dst]+=(float)(c.source.sample(src,0)*envelope);into[dst+1]+=(float)(c.source.sample(src,1)*envelope);}}}}float[] key(Track t,long pos,int n){if(t.sidechain==null)return null;Track k=session.track(t.sidechain);if(k==null||k==t)return null;float[] b=buffer(keys,k.id,n);if(!keyed.contains(k.id)){sum(k,pos,n,b);keyed.add(k.id);}return b;}void silence(Track t){t.meter=t.meterL=t.meterR=t.reduction=0;processors.remove(t.id);chains.remove(t.id);}void channel(Track t,long pos,int n,float[] out,float[] key){Processor fx=processors.get(t.id);if(fx==null||fx.wasBypassed!=t.bypassFx||fx.source!=t.fx){fx=new Processor();fx.wasBypassed=t.bypassFx;fx.source=t.fx;processors.put(t.id,fx);}Fx live=t.fx;if(!t.automation.isEmpty()){Fx sc=scratch.get(t.id);if(sc==null){sc=new Fx();scratch.put(t.id,sc);}live=Pro.automatedFx(t,pos,sc);}fx.configure(live,session.bpm);if(!t.bypassFx)fx.apply(temp,n,key);t.reduction=t.bypassFx?0:(float)Math.max(0,-20*Math.log10(fx.compGain*fx.peakGain));if(!t.inserts.isEmpty()){Pro.Chain chain=chains.get(t.id);if(chain==null){chain=new Pro.Chain();chains.put(t.id,chain);}if(!t.bypassFx){chain.process(t.inserts,temp,n,session.bpm);t.reduction=(float)Math.max(t.reduction,chain.reduction);}}else if(!chains.isEmpty())chains.remove(t.id);double volume=Pro.automated(t,"volume",pos,t.volume),pan=Pro.automated(t,"pan",pos,t.pan);double angle=(pan+1)*Math.PI/4,lg=Math.cos(angle)*volume,rg=Math.sin(angle)*volume;double left=Double.isNaN(fx.lastLeft)?lg:fx.lastLeft,right=Double.isNaN(fx.lastRight)?rg:fx.lastRight,dl=(lg-left)/n,dr=(rg-right)/n;float[] dest=out;if(!t.bus&&t.output!=null&&session.bus(t.output)!=null)dest=buffer(busBuffers,t.output,n);boolean sends=!t.bus&&!t.sends.isEmpty(),delayed=pdcOn;float meter=0,ml=0,mr=0;for(int i=0;i<n;i++){left+=dl;right+=dr;float l=(float)(temp[2*i]*left),r=(float)(temp[2*i+1]*right);if(delayed){post[2*i]=l;post[2*i+1]=r;}else{dest[2*i]+=l;dest[2*i+1]+=r;}if(sends){post[2*i]=l;post[2*i+1]=r;}ml=Math.max(ml,Math.abs(l));mr=Math.max(mr,Math.abs(r));meter=Math.max(ml,mr);}fx.lastLeft=lg;fx.lastRight=rg;t.meter=Math.max(meter,t.meter*.8f);t.meterL=Math.max(ml,t.meterL*.82f);t.meterR=Math.max(mr,t.meterR*.82f);t.peakHold=Math.max(t.peakHold,meter);int myLat=delayed?pdcLat.getOrDefault(t.id,0):0;if(delayed){int d=t.bus?pdcM-(pdcBusIn.getOrDefault(t.id,0)+myLat):dest==out?pdcM-myLat:pdcBusIn.getOrDefault(t.output,0)-myLat;pdcAdd(t.id+">out",post,dest,n,d);}if(sends)for(Pro.Send x:t.sends){if(session.bus(x.bus)==null)continue;double level=Pro.automated(t,"send:"+x.bus,pos,x.level);if(level<=0)continue;float[] b=buffer(busBuffers,x.bus,n),src=x.pre?temp:post;if(delayed){float[] scaled=sendScratch(n);for(int i=0;i<n*2;i++)scaled[i]=(float)(src[i]*level);pdcAdd(t.id+">"+x.bus,scaled,b,n,pdcBusIn.getOrDefault(x.bus,0)-myLat);}else for(int i=0;i<n*2;i++)b[i]+=(float)(src[i]*level);}}float[] sendBuf=new float[0];float[] sendScratch(int n){if(sendBuf.length<n*2)sendBuf=new float[n*2];return sendBuf;}public void render(long pos,int n,float[] out,boolean click){overloaded=false;Arrays.fill(out,0,n*2,0);if(session.referenceOn&&session.reference!=null){reference(pos,n,out);return;}computePdc();if(temp.length<n*2){temp=new float[n*2];post=new float[n*2];}keyed.clear();boolean solo=false;for(Track t:session.tracks)if(t.solo)solo=true;for(Track b:session.buses)Arrays.fill(buffer(busBuffers,b.id,n),0,n*2,0);for(Track t:session.tracks){if(t.mute||(solo&&!t.solo)){silence(t);continue;}sum(t,pos,n,temp);channel(t,pos,n,out,key(t,pos,n));}for(Track b:session.buses){if(b.mute){silence(b);continue;}System.arraycopy(buffer(busBuffers,b.id,n),0,temp,0,n*2);channel(b,pos,n,out,key(b,pos,n));}boolean pro=!session.masterInserts.isEmpty()||session.masterAutomation!=null||session.timeSignature!=4||!session.tempoChanges.isEmpty();if(!pro){masterReduction=0;long beat=beat(session.bpm);float max=0,leftPeak=0,rightPeak=0;for(int i=0;i<n;i++){double l=out[2*i],r=out[2*i+1];if(click){long q=(pos+i)%beat;if(q<RATE*.025){double v=Math.sin(2*Math.PI*(q/(double)RATE)*(((pos+i)/beat)%4==0?1600:1000))*clickLevel*Math.exp(-q/(RATE*.006));l+=v;r+=v;}}l*=session.master;r*=session.master;double amp=Math.max(Math.abs(l),Math.abs(r)),target=amp>.89125?.89125/amp:1;overloaded|=amp>1;limiterGain=target<limiterGain?target:Math.min(target,limiterGain+.00003);l*=limiterGain;r*=limiterGain;out[2*i]=(float)Math.max(-.89125,Math.min(.89125,l));out[2*i+1]=(float)Math.max(-.89125,Math.min(.89125,r));leftPeak=Math.max(leftPeak,Math.abs(out[2*i]));rightPeak=Math.max(rightPeak,Math.abs(out[2*i+1]));max=Math.max(leftPeak,rightPeak);}peak=max;peakLeft=leftPeak;peakRight=rightPeak;limiterDb=(float)Math.max(0,-20*Math.log10(limiterGain));}else masterPro(pos,n,out,click);if(meterLoudness){loudness.feed(out,n);analyse(out,n);}}void analyse(float[] out,int n){int w=scopePos;double k=Math.exp(-n/(RATE*.3));double lr=0,ll=0,rr=0;for(int i=0;i<n;i++){double l=out[2*i],r=out[2*i+1];scope[w]=(float)((l+r)*.5);w=(w+1)%scope.length;lr+=l*r;ll+=l*l;rr+=r*r;}scopePos=w;corrLR=corrLR*k+lr;corrLL=corrLL*k+ll;corrRR=corrRR*k+rr;correlation=(float)Math.max(-1,Math.min(1,corrLR/Math.sqrt(corrLL*corrRR+1e-18)));}/** A/B: plays the reference track (looping, level-matched by referenceGain) instead of the mix, bypassing the master chain. */void reference(long pos,int n,float[] out){Clip c=session.reference;int len=Math.max(1,c.length);float max=0,lp=0,rp=0;double g=session.referenceGain;for(int i=0;i<n;i++){int src=c.offset+(int)((pos+i)%len);if(src>=c.source.frames())continue;float l=(float)Math.max(-1,Math.min(1,c.source.sample(src,0)*g)),r=(float)Math.max(-1,Math.min(1,c.source.sample(src,1)*g));out[2*i]=l;out[2*i+1]=r;lp=Math.max(lp,Math.abs(l));rp=Math.max(rp,Math.abs(r));}peak=Math.max(lp,rp);peakLeft=lp;peakRight=rp;limiterDb=0;masterReduction=0;for(Track t:session.tracks)t.meter=t.meterL=t.meterR=0;if(meterLoudness){loudness.feed(out,n);analyse(out,n);}}void masterPro(long pos,int n,float[] out,boolean click){Pro.TempoMap tm=tempoMap();int sig=tm.beatsPerBar();double g0=session.master,g1=session.master;Pro.Lane lane=session.masterAutomation;if(lane!=null){double a=lane.at(pos),b=lane.at(pos+n);if(!Double.isNaN(a)){g0=a;g1=b;}}for(int i=0;i<n;i++){double l=out[2*i],r=out[2*i+1];if(click){double bt=tm.beatAt(pos+i);long index=(long)Math.floor(bt+1e-9);long q=pos+i-tm.frameAt(index);if(q>=0&&q<RATE*.025){double v=Math.sin(2*Math.PI*(q/(double)RATE)*(index%sig==0?1600:1000))*clickLevel*Math.exp(-q/(RATE*.006));l+=v;r+=v;}}double g=g0+(g1-g0)*i/n;out[2*i]=(float)(l*g);out[2*i+1]=(float)(r*g);}masterChain.process(session.masterInserts,out,n,session.bpm);masterReduction=(float)masterChain.reduction;float max=0,leftPeak=0,rightPeak=0;for(int i=0;i<n;i++){double l=out[2*i],r=out[2*i+1];double amp=Math.max(Math.abs(l),Math.abs(r)),target=amp>.89125?.89125/amp:1;overloaded|=amp>1;limiterGain=target<limiterGain?target:Math.min(target,limiterGain+.00003);l*=limiterGain;r*=limiterGain;out[2*i]=(float)Math.max(-.89125,Math.min(.89125,l));out[2*i+1]=(float)Math.max(-.89125,Math.min(.89125,r));leftPeak=Math.max(leftPeak,Math.abs(out[2*i]));rightPeak=Math.max(rightPeak,Math.abs(out[2*i+1]));max=Math.max(leftPeak,rightPeak);}peak=max;peakLeft=leftPeak;peakRight=rightPeak;limiterDb=(float)Math.max(0,-20*Math.log10(limiterGain));}}
 public static float[] drumPattern(int bpm,boolean[][] steps,int bars){int frames=(int)(beat(bpm)*4*bars);float[] out=new float[frames*2];Random random=new Random(9342);int step=(int)(RATE*60.0/bpm/4);for(int bar=0;bar<bars;bar++)for(int i=0;i<16;i++)for(int lane=0;lane<3;lane++)if(steps[lane][i]){int at=bar*step*16+i*step;int len=(int)(RATE*(lane==0?.38:lane==1?.18:.075));double phase=0,last=0;for(int j=0;j<len&&at+j<frames;j++){double t=j/(double)RATE,x;if(lane==0){phase+=2*Math.PI*(45+110*Math.exp(-t*42))/RATE;x=Math.sin(phase)*Math.exp(-t*13)*.75;}else{double noise=random.nextDouble()*2-1,hp=noise-last;last=noise;x=hp*Math.exp(-t*(lane==1?28:70))*(lane==1?.18:.1);if(lane==1)x+=Math.sin(2*Math.PI*180*t)*Math.exp(-t*30)*.12;}out[2*(at+j)]+=x;out[2*(at+j)+1]+=x;}}return out;}
 public static float[] note(int midi,double seconds,int tone){int n=(int)(RATE*seconds);float[] out=new float[n*2];double f=440*Math.pow(2,(midi-69)/12.0);for(int i=0;i<n;i++){double t=i/(double)RATE,phase=2*Math.PI*f*t,attack=Math.min(1,t/.008),release=Math.min(1,(seconds-t)/.06),env=attack*release*Math.exp(-t*(tone==1?3:1.2));double x=tone==0?Math.sin(phase)*.5+Math.sin(phase*2)*.13+Math.sin(phase*3)*.04:tone==1?Math.sin(phase+.9*Math.sin(phase*2)*Math.exp(-t*3))*.6:Math.sin(phase)*.7+Math.sin(phase*.5)*.15;out[2*i]=(float)(x*env*.32);out[2*i+1]=(float)(x*env*.32);}return out;}
 public static float[] chordPattern(int bpm,int tone){int bar=(int)(beat(bpm)*4);float[] out=new float[bar*4*2];int[][] chords={{53,57,60},{48,52,55},{46,50,53},{46,50,53}};for(int b=0;b<4;b++)for(int note:chords[b]){float[] part=note(note,bar/(double)RATE,tone);for(int i=0;i<part.length;i++)out[b*bar*2+i]+=part[i]*.65f;}return out;}
